### TL;DR code snippet (copy-paste)

```kotlin
// ---- 1. Custom HttpRequest -------------------------------------------------
class VaultHttpRequest(private val stock: HttpRequest) : HttpRequest {
    override fun executeRequest(
        responder: HttpResponder,
        nativePtr: Long,
        resourceUrl: String,
        dataRange: String?,
        etag: String?,
        modified: String?,
        offlineUsage: Boolean
    ) {
        if (!resourceUrl.startsWith("vault://")) {
            return stock.executeRequest(
                responder, nativePtr, resourceUrl, dataRange, etag, modified, offlineUsage
            )
        }

        val bytes = Vault.decryptTile(resourceUrl)
            ?: run {
                responder.handleFailure(HttpRequest.CONNECTION_ERROR,
                    "Failed to decrypt $resourceUrl")
                return
            }

        responder.onResponse(200, null, null, null, null, null, null, bytes)
    }

    override fun cancelRequest() = stock.cancelRequest()
}

// ---- 2. Install the provider (once, before any MapView) --------------------
val stock = MapLibre.getModuleProvider()
MapLibre.setModuleProvider(object : ModuleProvider by stock {
    override fun createHttpRequest(): HttpRequest = VaultHttpRequest(stock.createHttpRequest())
})

// ---- 3. Load a style that uses vault:// URLs --------------------------------

Below is a **complete, copy-and-paste-ready TypeScript example** that shows how to:

1. **Create an IndexedDB database** (`tileCache`) that stores raw MVT bytes under the key  
   `z/x/y` (you can adapt the key format to whatever you like).  
2. **Register a custom URL scheme** (`cache://`) with **MapLibre GL JS** using the
   `maplibregl.addProtocol` API (available since v4.0.0).  
3. **Serve the tiles** from the IndexedDB cache when the style references URLs such as  
   `cache://tiles/{z}/{x}/{y}`.  
4. **Fallback to the network** (or any other source) when a tile is missing in the cache.

> **TL;DR** – Put the code in a module that runs **before** you create the `Map` instance, then use `cache://…` URLs in your style JSON.

---

## 1️⃣  Install the tiny helper library (optional but makes IndexedDB painless)

```bash
npm i idb
```

`idb` is a tiny wrapper around the native IndexedDB API that gives you a Promise-based
interface and works in all modern browsers.

---

## 2️⃣  IndexedDB helper – `tileCache.ts`

```ts
// tileCache.ts
import { openDB, DBSchema, IDBPDatabase } from 'idb';

/**
 * The shape of the IndexedDB we will use.
 *
 *   store: "tiles"
 *   key:   `${z}/${x}/${y}`   (string)
 *   value: Uint8Array (raw MVT bytes)
 */
interface TileCacheDB extends DBSchema {
  tiles: {
    key: string;               // e.g. "12/3456/7890"
    value: Uint8Array;         // raw MVT bytes
  };
}

/** Singleton DB instance – created on first use */
let dbPromise: Promise<IDBPDatabase<TileCacheDB>> | null = null;

/** Open (or create) the DB */
function getDB(): Promise<IDBPDatabase<TileCacheDB>> {
  if (!dbPromise) {
    dbPromise = openDB<TileCacheDB>('tileCache', 1, {
      upgrade(db) {
        db.createObjectStore('tiles');
      },
    });
  }
  return dbPromise;
}

/** Store a tile (used by your own downloader / pre-loader) */
export async function putTile(
  z: number,
  x: number,
  y: number,
  data: Uint8Array,
): Promise<void> {
  const db = await getDB();
  const key = `${z}/${x}/${y}`;
  await db.put('tiles', data, key);
}

/** Retrieve a tile – returns `undefined` if not cached */
export async function getTile(
  z: number,
  x: number,
  y: number,
): Promise<Uint8Array | undefined> {
  const db = await getDB();
  const key = `${z}/${x}/${y}`;
  return db.get('tiles', key);
}

/** Utility – delete everything (useful while developing) */
export async function clearCache(): Promise<void> {
  const db = await getDB();
  await db.clear('tiles');
}
```

> **Why `Uint8Array`?**  
> MapLibre expects the protocol handler to resolve with an `ArrayBuffer` (or a
> `Response` object). `Uint8Array` is a thin wrapper around an `ArrayBuffer` and
> works directly with the API.

---

## 3️⃣  Register the `cache://` protocol – `registerCacheProtocol.ts`

```ts
// registerCacheProtocol.ts
import maplibregl from 'maplibre-gl';
import { getTile } from './tileCache';

/**
 * Register a custom protocol that reads vector tiles from IndexedDB.
 *
 * The handler receives an object with:
 *   - url: the full URL string (e.g. "cache://tiles/12/3456/7890")
 *   - params: {z, x, y, ...} – the same values MapLibre extracts from the URL.
 *   - abort: AbortSignal – you can respect it if you do a network request.
 *
 * The handler must **return a Promise** that resolves to:
 *   - an ArrayBuffer / Uint8Array (the raw tile bytes), **or**
 *   - a `Response` object (e.g. `new Response(arrayBuffer, {status:200})`).
 *
 * If the promise resolves to `null`/`undefined`, MapLibre treats the tile as
 * missing and will fire a `tileerror` event.
 */
export function registerCacheProtocol(): void {
  // The protocol name is everything before the first colon.
  // In our case: "cache"
  maplibregl.addProtocol('cache', async (params, abort) => {
    // `params` contains the parsed URL parts.
    // Example URL: cache://tiles/12/3456/7890
    // => params.path = "/tiles/12/3456/7890"
    // => params.z = 12, params.x = 3456, params.y = 7890
    const { z, x, y } = params;

    // 1️⃣ Try to read the tile from IndexedDB
    const cached = await getTile(z, x, y);
    if (cached) {
      // Return the raw bytes – MapLibre will treat it as a valid MVT tile.
      return cached.buffer; // Uint8Array → ArrayBuffer
    }

    // 2️⃣ If not cached, you can either:
    //   a) return `null` → MapLibre will fire a tileerror (good for “offline-only” mode)
    //   b) fall back to the network (example below)
    //   c) throw an error to surface the problem in the console.

    // ---- Example fallback to network (optional) ----
    // const networkUrl = `https://my.tileserver.com/${z}/${x}/${y}.pbf`;
    // const response = await fetch(networkUrl, { signal: abort });
    // if (!response.ok) return null; // let MapLibre handle the error
    // const arrayBuffer = await response.arrayBuffer();
    // // Optionally store it for next time:
    // // await putTile(z, x, y, new Uint8Array(arrayBuffer));
    // return arrayBuffer;
    // ------------------------------------------------

    // For a pure-cache-only approach:
    return null; // → MapLibre will emit a tileerror event.
  });
}
```

**Important notes**

| Situation | What you must do |
|-----------|------------------|
| **You want the cache to be the *only* source** | Return `null` (or `undefined`) when the tile is missing. MapLibre will keep the layer but the tile will be blank; you can listen to `tileerror` to show a placeholder. |
| **You want a network fallback** | Use `fetch` inside the handler (as shown in the commented block) and optionally `putTile` the result back into IndexedDB for future offline use. |
| **You need to respect cancellation** | The `abort` signal is passed in; if you start a network request, pass `{signal: abort}` to `fetch`. If the request is aborted, just return `null`. |
| **You need to serve raster tiles** | The same handler works – just return the raster bytes (PNG/JPEG) instead of MVT. |

