## 4️⃣  Put it all together – `main.ts`

```ts
// main.ts
import maplibregl from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css'; // if you use a bundler that handles CSS
import { registerCacheProtocol } from './registerCacheProtocol';
import { putTile } from './tileCache';

// ---------------------------------------------------
// 1️⃣  Register the protocol **before** creating the map
// ---------------------------------------------------
registerCacheProtocol();

// ---------------------------------------------------
// 2️⃣  (Optional) Pre-populate the cache for demo purposes
// ---------------------------------------------------
async function preloadDemoTiles() {
  // Example: download a few tiles from a public source and store them.
  const demoUrl = (z: number, x: number, y: number) =>
    `https://demotiles.maplibre.org/tiles/planet/${z}/${x}/${y}.pbf`;

  const z = 2, x = 1, y = 1; // pick any tile you like
  const resp = await fetch(demoUrl(z, x, y));
  if (resp.ok) {
    const bytes = new Uint8Array(await resp.arrayBuffer());
    await putTile(z, x, y, bytes);
    console.log(`Demo tile ${z}/${x}/${y} cached`);
  }
}
preloadDemoTiles().catch(console.error);

// ---------------------------------------------------
// 3️⃣  Create the MapLibre map – style can now use cache:// URLs
// ---------------------------------------------------
const map = new maplibregl.Map({
  container: 'map',               // id of the <div> in your HTML
  style: {
    version: 8,
    sources: {
      // The source points to the custom scheme.
      // The `{z}/{x}/{y}` placeholders are automatically replaced by MapLibre.
      myTiles: {
        type: 'vector',
        // The part after the scheme is just a path – MapLibre ignores it,
        // but we keep a nice structure for readability.
        url: 'cache://tiles/{z}/{x}/{y}'
      }
    },
    layers: [
      {
        id: 'land',
        type: 'fill',
        source: 'myTiles',
        'source-layer': 'land', // depends on the source's layer name
        paint: { 'fill-color': '#e0e0e0' }
      }
    ]
  },
  center: [0, 0],
  zoom: 2,
});

// ---------------------------------------------------
// 4️⃣  Listen for missing-tile errors (useful for debugging)
// ---------------------------------------------------
map.on('error', (e) => {
  // e.error contains the original error object.
  console.warn('MapLibre error:', e.error);
});

map.on('tileerror', (e) => {
  console.warn(
    `Tile error – source:${e.source?.id} z:${e.tile?.z} x:${e.tile?.x} y:${e.tile?.y}`
  );
});
```

